// OpenChiip Agent Desktop — Tauri 2.0 入口
// 启动 sidecar 后端进程（PyInstaller 打包的独立 exe），嵌入 WebView 访问 localhost:8900

#![cfg_attr(not(debug_assertions), windows_subsystem = "windows")]

use std::sync::Mutex;
use std::thread;
use std::time::Duration;
use tauri::Manager;
use tauri_plugin_shell::ShellExt;
use tauri_plugin_shell::process::CommandChild;

/// 启动 sidecar 后端进程
fn start_backend(app: &tauri::AppHandle) -> Option<CommandChild> {
    let shell = app.shell();
    match shell.command("openchiip-harness-backend")
        .env("HARNESS_HOST", "127.0.0.1")
        .env("HARNESS_PORT", "8900")
        .spawn()
    {
        Ok((_rx, child)) => {
            eprintln!("[Tauri] 后端 sidecar 已启动, PID={}", child.pid());
            // 等待后端就绪
            thread::sleep(Duration::from_secs(3));
            Some(child)
        }
        Err(e) => {
            eprintln!("[Tauri] 启动后端 sidecar 失败: {}", e);
            None
        }
    }
}

fn main() {
    tauri::Builder::default()
        .plugin(tauri_plugin_shell::init())
        .setup(|app| {
            let handle = app.handle().clone();
            let backend = start_backend(&handle);
            app.manage(BackendHandle {
                child: Mutex::new(backend),
            });
            Ok(())
        })
        .on_window_event(|window, event| {
            if let tauri::WindowEvent::Destroyed = event {
                let state = window.state::<BackendHandle>();
                let child = {
                    let mut guard = state.child.lock().unwrap();
                    guard.take()
                };
                if let Some(child) = child {
                    let _ = child.kill();
                    eprintln!("[Tauri] 后端 sidecar 已终止");
                }
            }
        })
        .run(tauri::generate_context!())
        .expect("启动 Tauri 应用失败");
}

/// 持有后端 sidecar 进程句柄
struct BackendHandle {
    child: Mutex<Option<CommandChild>>,
}
